using System;using System.IO;using System.Linq;using System.Collections.Generic;
internal static class ParentChildPresetTests {
 static int checks;static void Check(bool v,string m){checks++;if(!v)throw new Exception(m);}
 static Track Parent(string kind){return new Track{id="parent",name="母体",kind=kind,start=0,end=kind=="emitter"?0:100,x=100,y=100,count=1,speed=2,life=100,lifetimeMode="fixed",deathEffect="none",advancedBullets=true};}
 static EditorState Scene(Track p){return new EditorState{fps=50,duration=120,tracks=new List<Track>{p}};}
 static void Main(string[] args){
 foreach(string kind in new[]{"emitter","object","rod","group"})foreach(string key in new[]{GenerationPresets.ChildBurst,GenerationPresets.ReplacementBurst}){
 var p=Parent(kind);var s=Scene(p);var a=GenerationPresets.Apply(s,p,key);var c=s.tracks.Single(t=>t.id==a.templateId);Check(a.start==50&&a.spawnRepeat==0&&a.maxGeneration==4,"single delayed rule");Check(c.templateOnly&&s.tracks.All(t=>t.keyframes.Count==0),"native zero-keyframe graph");Check(c.spriteFrame==-1,"automatic frame convention");Check((kind=="emitter"?p.bulletActions:p.spawnActions).Contains(a),"source scope");
 if(kind=="group")s.tracks.Add(new Track{id="member",kind="object",parentId=p.id,start=0,end=100});
 Motion.Normalize(s);File.WriteAllText(Path.Combine(args[0],kind+"-"+key+".json"),Json.Write(s));
 var clone=Json.Read<EditorState>(Json.Write(s));Motion.Normalize(clone);Check(clone.tracks[0].id==p.id&&clone.tracks[1].spriteFrame==-1,"JSON identity/frame");
 foreach(var copies in new[]{BulletSystem.CloneTracks(s.tracks),TrackPreset.Capture("family",s.tracks,50).Instantiate(0,50)}){var cp=copies.Single(t=>t.name=="母体");var ca=TemplateRuntime.Actions(cp).Single();Check(cp.id!=p.id&&ca.templateId!=a.templateId&&copies.Any(t=>t.id==ca.templateId),"clone/preset graph remap");}
 var snapshot=s.Snapshot();var bag=new NativeProperties();GenerationPresets.Fields(bag,s,p,a,change=>change(),kind!="emitter");var props=bag.GetProperties();props["每次发射数量"].SetValue(bag,7);props["新弹幕速度"].SetValue(bag,4.0);props["贴图帧（-1 自动）"].SetValue(bag,2.0);Check(c.count==7&&c.speed==4&&c.spriteFrame==2&&s.tracks.Count==(kind=="group"?3:2),"edit same linked template");Check(snapshot.tracks[1].count==12&&snapshot.tracks[1].spriteFrame==-1,"undo snapshot isolated");
 props["贴图帧（-1 自动）"].SetValue(bag,-1.0);props["每次发射数量"].SetValue(bag,12);props["新弹幕速度"].SetValue(bag,3.0);
 if(kind!="group"){var w=new BulletWorld(s);w.Seek(49);Check(!w.bullets.Any(b=>b.generation==1),"not before delay");w.Seek(50);Check(w.bullets.Count(b=>b.generation==1)==12,"burst at delay");if(kind=="emitter")Check(w.bullets.Any(b=>b.source.id==p.id&&!b.dead)==(key==GenerationPresets.ChildBurst),"retire only replacement");w.Seek(51);Check(w.bullets.Count(b=>b.generation==1)==12,"one shot");w.Seek(0);w.Seek(50);Check(w.bullets.Count(b=>b.generation==1)==12,"reverse rebuild");}
 s.tracks.Remove(c);bag=new NativeProperties();GenerationPresets.Fields(bag,s,p,a,change=>change());Check(bag.GetProperties()["关联子模板"].GetValue(bag).ToString().Contains("缺失"),"deleted link warning");var missing=new BulletWorld(s);missing.Seek(50);if(kind=="emitter")Check(missing.bullets.Any(b=>b.source.id==p.id&&!b.dead),"missing child cannot retire parent");a.templateId="";bag=new NativeProperties();GenerationPresets.Fields(bag,s,p,a,change=>change());Check(bag.GetProperties().Count==1,"empty ID safe");
 }
 {var p=Parent("emitter");p.templateOnly=true;var s=Scene(p);var a=GenerationPresets.Apply(s,p,GenerationPresets.ChildBurst);a.start=2;var host=Parent("object");host.id="host";host.spawnActions.Add(new BulletAction{type="spawn",templateId=p.id,start=0,duration=0,maxGeneration=4});s.tracks.Add(host);Motion.Normalize(s);var w=new BulletWorld(s);w.Seek(2);Check(w.bullets.Count(b=>b.generation==2)==12,"template-born mother produces second generation");File.WriteAllText(Path.Combine(args[0],"nested.json"),Json.Write(s));}
 {var p=Parent("emitter");var s=Scene(p);var a=GenerationPresets.Apply(s,p,GenerationPresets.ChildBurst);var before=Json.Write(s);var draft=p.bulletActions.Select(row=>row.Snapshot()).ToList();draft[0].start=3;draft[0].spawnTiming="action-time";draft[0].destroyParent=true;draft.Clear();Check(Json.Write(s)==before,"discarded action draft leaves source and child unchanged (cancel model)");var bag=new NativeProperties();GenerationPresets.TimingFields(bag,a,false,change=>change());bag.GetProperties()["生成执行时点"].SetValue(bag,"行为顺序内（立即生成）");Check(a.spawnTiming=="action-time","inline timing binding");GenerationPresets.TimingFields(new NativeProperties(),a,true,change=>{throw new Exception("object timing must be read only");});}
 foreach(string timing in new[]{"after-move","action-time"}){var p=Parent("emitter");var s=Scene(p);var a=GenerationPresets.Apply(s,p,GenerationPresets.ReplacementBurst);a.spawnTiming=timing;a.start=2;var w=new BulletWorld(s);w.Seek(2);Check(w.bullets.Where(b=>b.generation==1).All(b=>Math.Abs(b.sourceX-(timing=="after-move"?104:102))<.00001),"movement order "+timing);File.WriteAllText(Path.Combine(args[0],timing+".json"),Json.Write(s));}
 {var p=Parent("emitter");var s=Scene(p);var a=GenerationPresets.Apply(s,p,GenerationPresets.ChildBurst);var b=GenerationPresets.Apply(s,p,GenerationPresets.ChildBurst);Check(a.templateId!=b.templateId&&s.tracks.Count==3,"repeated apply independent IDs");bool bad=false;try{GenerationPresets.Apply(Scene(Parent("emitter")),p,GenerationPresets.ChildBurst);}catch(ArgumentException){bad=true;}Check(bad,"stale source from different project rejected");p.id="";bad=false;try{GenerationPresets.Apply(s,p,GenerationPresets.ChildBurst);}catch(ArgumentException){bad=true;}Check(bad,"empty source ID rejected");}
 {var p=Parent("emitter");var s=Scene(p);var old=GenerationPresets.Apply(s,p,"aim-player");Check(old.start==0&&old.spawnRepeat==25&&!old.destroyParent&&old.maxGeneration==4,"old preset unchanged");var legacy=Json.Read<EditorState>("{\"tracks\":[{\"id\":\"old\",\"kind\":\"emitter\"}]}");Motion.Normalize(legacy);Check(legacy.tracks[0].spawnActions.Count==0,"old project compatible");}
 Console.WriteLine("PASS "+checks+" parent/child model and property checks");
 }
}
